/**
 * The site's own pages — the imprint, the terms, the community rules and the
 * privacy notice — in every language the site speaks. English is the text
 * that applies (`shared/legal.ts`, and the rules and trust levels in
 * `shared/talkback.ts`); every other language is a translation to read by,
 * and says so above its words (`applies`, `{page}` being the English page).
 *
 * A line may name `{contact}`, link one of the site's own pages as
 * `[words](/path)`, and set words in *italics*, as in `shared/legal.ts`. The
 * trust levels' names and what each allows are Talkback's own words for them.
 */

import type { Lang } from "../src/v4/i18n/strings";
import { IMPRINT_MISSING, IMPRINT_WHAT, NO_CONTACT, PRIVACY, PRIVACY_INTRO, PRIVACY_OUTRO, SCREENING, TERMS, TERMS_INTRO, type Clause } from "./legal";
import { RULES, TRUST } from "./talkback";

export type LegalPage = "imprint" | "terms" | "rules" | "privacy";

export interface LegalWords {
  title: Record<LegalPage, string>;
  subtitle: Record<LegalPage, string>;
  /** Above a translation: the English text is the one that applies. Empty in English. */
  applies: string;
  /** The imprint's labels. */
  labels: { runBy: string; address: string; email: string; what: string };
  imprintWhat: string;
  imprintMissing: string;
  noContact: string;
  screening: string;
  termsIntro: string;
  terms: Clause[];
  privacyIntro: string;
  privacy: Clause[];
  privacyOutro: string;
  rules: string[];
  /** The heading over the trust levels. */
  grows: string;
  trust: { name: string; about: string }[];
}

const EN: LegalWords = {
  title: { imprint: "Imprint", terms: "Terms of use", rules: "Community rules", privacy: "Privacy" },
  subtitle: { imprint: "Who runs this site.", terms: "What you agree to when you post or upload here.", rules: "The good parts only.", privacy: "What this site keeps about you, and why." },
  applies: "",
  labels: { runBy: "Run by", address: "Address", email: "E-mail", what: "What it is" },
  imprintWhat: IMPRINT_WHAT,
  imprintMissing: IMPRINT_MISSING,
  noContact: NO_CONTACT,
  screening: SCREENING,
  termsIntro: TERMS_INTRO,
  terms: TERMS,
  privacyIntro: PRIVACY_INTRO,
  privacy: PRIVACY,
  privacyOutro: PRIVACY_OUTRO,
  rules: [...RULES],
  grows: "How a new account grows in",
  trust: TRUST.map((t) => ({ name: t.name, about: t.about })),
};

